"""Bundled sample dataset (synthetic, generated by samples/generate.py)."""

from __future__ import annotations

from pathlib import Path

from ingest.parsers import RawTable, parse_csv

SAMPLES_DIR = Path(__file__).resolve().parent.parent / "samples"
SAMPLE_TABLES = ("customers", "products", "orders", "order_items")
SAMPLE_NAME = "Sample store data"


def load_sample_tables(max_rows: int) -> list[RawTable]:
    tables: list[RawTable] = []
    for name in SAMPLE_TABLES:
        path = SAMPLES_DIR / f"{name}.csv"
        tables.extend(parse_csv(path.name, path.read_bytes(), max_rows))
    return tables
